import type { MapItem } from "@/lib/map-utils";
import { SITE } from "../config/sites.ts";

export type { MapItem };
export type AreaKey = keyof typeof mapData;

export const AREAS = {
	greaterNoida: { slug: "greater-noida", name: "Greater Noida" },
	yamunaExpressway: { slug: "yamuna-expressway", name: "Yamuna Expressway" },
	noidaExtension: { slug: "noida-extension", name: "Noida Extension" },
} as const satisfies Record<AreaKey, { slug: string; name: string }>;

/**
 * Display order, matching how Shiva Associates sequence their map pages.
 *
 * Their Greater Noida page runs residential sectors first (ALPHA, BETA,
 * CHI-PHI, DELTA, ETA, GAMMA … ZETA), then industrial (ECOTECH, SURAJPUR,
 * TECH ZONE, TOY CITY), then institutional (KNOWLEDGE PARK). Their Yamuna page
 * is sector maps in numeric order — SECTOR-16, 17, 18 PART-1A…7F, 20 PART-A…U,
 * 21, 22D, 24, 29, 32, 33 — with villages kept separate.
 *
 * So: bucket by category, then sort naturally inside each bucket, with
 * numbered sectors ordered by sector number rather than as text.
 */
const CATEGORY: { rank: number; test: RegExp }[] = [
	// Numbered sectors lead (this is what dominates the Yamuna listing).
	{ rank: 0, test: /^(PART\s+)?SECTOR[\s-]*\d/i },
	// Institutional and industrial are called out before general residential
	// only when the name says so; otherwise they fall through to residential.
	{ rank: 2, test: /ECOTECH|UDYOG|TECH ZONE|TOY CITY|EPIP|INDUSTRIAL|SIKANDRABAD|SURAJPUR|SITE-V/i },
	{ rank: 3, test: /KNOWLEDGE PARK|INSTITUTIONAL/i },
	{ rank: 4, test: /ABADI|VILLAGE|VILL\.|^\d+\s*PERCENT|GROUP HOUSING/i },
	{ rank: 5, test: /^MASTER PLAN/i },
];

const SECTOR_RE = /^(PART\s+)?SECTOR[\s-]*\d/i;

/** 0 = numbered sector, 1 = named residential sector, 2+ = see CATEGORY. */
function categoryRank(name: string, sectorsLead: boolean): number {
	if (SECTOR_RE.test(name)) return sectorsLead ? 0 : 1;
	for (const { rank, test } of CATEGORY) if (test.test(name)) return rank;
	return 1;
}

/** Leading sector number, so SECTOR 20 follows SECTOR 18 rather than SECTOR 2. */
function sectorNumber(name: string): number {
	const m = name.match(/SECTOR[\s-]*(\d+)/i);
	return m ? Number(m[1]) : Number.MAX_SAFE_INTEGER;
}

const natural = (a: string, b: string) =>
	a.localeCompare(b, "en", { numeric: true, sensitivity: "base" });

/**
 * Whether numbered sectors lead the listing. On the Yamuna page they are
 * effectively the whole list, so Shiva order them numerically up front. On the
 * Greater Noida page there are only a handful, and they sit alphabetically
 * under "S" among ALPHA, BETA, DELTA and the rest.
 */
const sectorsDominate = (maps: MapItem[]) =>
	maps.filter((m) => SECTOR_RE.test(m.name)).length / maps.length > 0.4;

function compareMaps(a: MapItem, b: MapItem, sectorsLead: boolean): number {
	const ra = categoryRank(a.name, sectorsLead);
	const rb = categoryRank(b.name, sectorsLead);
	if (ra !== rb) return ra - rb;
	if (ra === 0) {
		const na = sectorNumber(a.name);
		const nb = sectorNumber(b.name);
		if (na !== nb) return na - nb;
	}
	return natural(a.name, b.name);
}

/**
 * Heading each category sits under in the grid. Indexes match the ranks in
 * CATEGORY / categoryRank, so the labels and the sort can never drift apart.
 */
const GROUP_LABEL = [
	"Sector layout plans",
	"Residential sectors",
	"Industrial areas",
	"Institutional & Knowledge Park",
	"Villages & abadi plans",
	"Master plans",
];

const sorted = (key: AreaKey): MapItem[] => {
	const maps = mapData[key] as MapItem[];
	const lead = sectorsDominate(maps);
	return [...maps]
		.sort((a, b) => compareMaps(a, b, lead))
		.map((m) => ({ ...m, group: GROUP_LABEL[categoryRank(m.name, lead)] }));
};

const ORDERED = Object.fromEntries(
	(Object.keys(mapData) as AreaKey[]).map((k) => [k, sorted(k)]),
) as Record<AreaKey, MapItem[]>;

/**
 * Only the regions this deployment owns. Greater Noida and Yamuna Expressway
 * are split across the two sites so neither publishes the other's map pages.
 */
/** The region's own master plan is the honest cover; fall back to the first map. */
const coverFor = (key: AreaKey) =>
	(ORDERED[key].find((m) => /^MASTER PLAN/i.test(m.name)) ?? ORDERED[key][0])
		.imageUrl;

export const AREA_LIST = SITE.areas.map((key) => ({
	key,
	...AREAS[key],
	count: ORDERED[key].length,
	cover: coverFor(key),
}));

type Area = (typeof AREA_LIST)[number];

const BY_SLUG = new Map<string, Area>(AREA_LIST.map((a) => [a.slug, a]));

export const getArea = (slug: string) => BY_SLUG.get(slug);

export const getMaps = (slug: string): MapItem[] => {
	const area = BY_SLUG.get(slug);
	return area ? ORDERED[area.key] : [];
};

export const getMap = (slug: string, id: string) =>
	getMaps(slug).find((m) => m.id === id);

/** Every map this site owns, with its area attached. */
export const ALL_MAPS = AREA_LIST.flatMap((area) =>
	ORDERED[area.key].map((map) => ({ ...map, area })),
);

/* ------------------------------------------------------------------ *
 * Related maps
 *
 * Every detail page previously had exactly one inbound internal link (its
 * area grid), which is a weak crawl signal across 176 pages. Grouping by
 * sector family — ECOTECH 1/2/3…, OMICRON 1/1A/2… — gives each page several
 * genuinely relevant neighbours.
 * ------------------------------------------------------------------ */

const NAME_PREFIX =
	/^(PROPOSED\s+|PORPOSED\s+|LAYOUT\s*PLAN\s+(OF|FOR)\s+|LAYOUTPLAN\s+OF\s+|ABADI\s+LAYOUT\s+PLAN\s+OF\s+|MASTER\s+PLAN\s+OF\s+|ABADI\s+(AT|EXTENSION\s+AT|EXPANSION\s+(FOR|OF)\s+)|GROUP\s+HOUSING\s+AT\s+|VILL\.?\s+|VILLAGE\s+|SECTOR\s+|SEC\s+)+/i;

/** Words that describe a parcel rather than name a sector. */
const GENERIC = new Set([
	"POCKET",
	"PART",
	"ABADI",
	"VILLAGE",
	"SITE",
	"AREA",
	"PHASE",
	"EXTENSION",
	"BLOCK",
	"PLAN",
	"MASTER",
	"LAYOUT",
]);

/** "LAYOUT PLAN OF ECOTECH 1 (EXTENSION)" -> "ECOTECH"; "" when unclear. */
function family(name: string): string {
	const words = name
		.toUpperCase()
		.replace(NAME_PREFIX, "")
		.replace(/[^A-Z0-9 -]/g, " ")
		.split(/\s+/)
		.filter(Boolean);
	const head = words.find((w) => /[A-Z]/.test(w));
	return head && !GENERIC.has(head) ? head : "";
}

/**
 * Maps related to `mapId`: same sector family first, then its nearest
 * neighbours in the area listing, so the result is never empty.
 */
export function relatedMaps(slug: string, mapId: string, limit = 6) {
	const maps = getMaps(slug);
	const index = maps.findIndex((m) => m.id === mapId);
	if (index === -1) return [];

	const own = family(maps[index].name);
	const picked = own
		? maps.filter((m, i) => i !== index && family(m.name) === own)
		: [];

	// Top up from either side of this map — the listing is alphabetical, so
	// neighbours are usually the same locality.
	for (let step = 1; picked.length < limit && step < maps.length; step++) {
		for (const i of [index - step, index + step]) {
			const candidate = maps[i];
			if (!candidate || picked.length >= limit) continue;
			if (i !== index && !picked.includes(candidate)) picked.push(candidate);
		}
	}

	return picked.slice(0, limit);
}
